{
  "requirement_definitions": [
    {
      "id": "DMSR-2465",
      "title": "Level 1 Data Quality Report Deﬁnition",
      "text": "The DMS shall produce a Level 1 Data Quality Report that contains indicators of data quality that result from running the DMS pipelines, including at least: Photometric zero point vs. time for each utilized ﬁlter; Sky brightness vs. time for each utilized ﬁlter; seeing vs. time for each utilized ﬁlter; PSF parameters vs. time for each utilized ﬁlter; detection eﬃciency for point sources vs. mag for each utilized ﬁlter."
    },
    {
      "id": "DMSR-5074",
      "title": "Level 1 Performance Report Deﬁnition",
      "text": "The DMS shall produce a Level 1 Performance Report that provides indicators of how the DMS has performed in processing the night’s observations, including at least: number of observations successfully processed through each pipeline; number of observations for each pipeline that had recoverable failures (with a record of the failure type and recovery mechanism); number of observations for each pipeline that had unrecoverable failures; number of observations archived at each DMS Facility; number of observations satisfying the science criteria for each active science program."
    },
    {
      "id": "DMSR-7584",
      "title": "Level 1 Calibration Report Deﬁnition",
      "text": "The DMS shall produce a Level 1 Calibration Report that provides a summary of signiﬁcant diﬀerences in Calibration Images that may indicate evolving problems with the telescope or camera, including a nightly broad-band ﬂat in each ﬁlter."
    },
    {
      "id": "DMSR-6110",
      "title": "Data Management Nightly Reporting",
      "text": "The LSST Data Management subsystem shall produce a searchable - interactive nightly report(s), from information published in the EFD by each subsystem, summarizing performance and behavior over a user deﬁned period of time (e.g. the previous 24 hours)."
    },
    {
      "id": "DMSR-5745",
      "title": "Regenerating L1 Data Products During Data Release Processing",
      "text": "During Data Release Processing, all the Level 1 data products shall be regenerated using the current best algorithms."
    },
    {
      "id": "DMSR-6213",
      "title": "Publishing predicted visit schedule",
      "text": "A service shall be provided to publish to the community the next visit location and the predicted visit schedule provided by the OCS. This service shall consist of both a web page for human inspection and a web API to allow automated tools to respond promptly."
    },
    {
      "id": "DMSR-5359",
      "title": "Persisting Data Products",
      "text": "All per-band deep coadds and best seeing coadds shall be kept indeﬁnitely and made available to users."
    }
  ],
